import json
d = json.load(open('impl-plan.json', encoding='utf-8'))
tasks = d['tasks']
ids = [t['id'] for t in tasks]
assert len(ids) == len(set(ids)), 'duplicate ids'
idset = set(ids)

# dependsOn references only in-plan ids, no self-ref
for t in tasks:
    for dep in t['dependsOn']:
        assert dep in idset, f'{t[\"id\"]} depends on unknown {dep}'
        assert dep != t['id'], f'{t[\"id\"]} self-depends'

# simple cycle check via DFS
def has_cycle():
    WHITE, GRAY, BLACK = 0, 1, 2
    color = {t['id']: WHITE for t in tasks}
    dep_map = {t['id']: t['dependsOn'] for t in tasks}
    def visit(n):
        color[n] = GRAY
        for m in dep_map[n]:
            if color[m] == GRAY:
                return True
            if color[m] == WHITE and visit(m):
                return True
        color[n] = BLACK
        return False
    return any(color[n] == WHITE and visit(n) for n in color)
assert not has_cycle(), 'cycle detected'

# milestone is terminal (no other task depends on it)
milestones = [t['id'] for t in tasks if t['unitType']=='milestone']
for t in tasks:
    for dep in t['dependsOn']:
        assert dep not in milestones or t['id'] in milestones, f'{t[\"id\"]} depends on milestone {dep}'
# actually stricter: nothing should depend on milestone at all
for t in tasks:
    for dep in t['dependsOn']:
        assert dep not in milestones, f'{t[\"id\"]} (non-milestone) depends on milestone {dep}'

# milestone depends on all implementation tasks
impl_ids = [t['id'] for t in tasks if t['unitType']=='implementation']
for m in milestones:
    mt = next(t for t in tasks if t['id']==m)
    missing = [i for i in impl_ids if i not in mt['dependsOn']]
    assert not missing, f'milestone {m} missing deps {missing}'

# ownedBoundary: no protected paths, no absolute/.. , non-overlap across tasks
import os
all_paths = []
for t in tasks:
    ob = t['ownedBoundary']
    assert ob, f'{t[\"id\"]} empty ownedBoundary'
    for p in ob:
        assert not p.startswith('/') and ':' not in p and '..' not in p.split('/'), f'bad path {p}'
        assert not p.startswith('.claude') and p != 'docs/solution-design.md' and not (p.startswith('docs/') and p.endswith('.md')), f'protected path claimed {p}'
        all_paths.append((t['id'], p))

for i in range(len(all_paths)):
    for j in range(i+1, len(all_paths)):
        id1, p1 = all_paths[i]
        id2, p2 = all_paths[j]
        if id1 == id2:
            continue
        n1, n2 = os.path.normpath(p1), os.path.normpath(p2)
        assert not (n1==n2 or n1.startswith(n2+os.sep) or n2.startswith(n1+os.sep)), f'overlap {all_paths[i]} vs {all_paths[j]}'

# delegation 8 fields
deleg_keys = {'from','to','task','input','output','done','context','constraints'}
for t in tasks:
    dk = set(t['delegation'].keys())
    assert dk == deleg_keys, f'{t[\"id\"]} delegation keys mismatch: {dk}'
    assert t['role']=='Worker' and t['model']=='sonnet'

# each task's own done AC is a syntactically valid standalone command (extract python -c payload and compile it)
import re
for t in tasks:
    done = t['done']
    assert done.startswith('python -c \"') and done.endswith('\"'), f'{t[\"id\"]} done not single python -c form: {done[:50]}'
    payload = done[len('python -c \"'):-1]
    # unescape the doubled quotes is not needed since inner uses single quotes
    compile(payload, '<done-ac>', 'exec')

print('ALL EXTENDED CHECKS PASSED:', len(tasks), 'tasks', ids)
